Here is the idiomatic Rust port of your TypeScript LRU cache. It uses Tokio for the background eviction loop, `Arc<Mutex<...>>` for thread-safe shared state, and an efficient `VecDeque` with access sequence IDs to maintain LRU order without `O(N)` shifts or expensive `.clone()` calls on string keys during the hot path.

### `Cargo.toml`

```toml
[package]
name = "lru_cache_rs"
version = "0.1.0"
edition = "2021"

[dependencies]
tokio = { version = "1", features = ["full"] }
```

### `src/lib.rs`

```rust
use std::collections::{HashMap, VecDeque};
use std::sync::{Arc, Mutex, Weak};
use std::time::{SystemTime, UNIX_EPOCH};
use tokio::task::JoinHandle;
use tokio::time::{interval, Duration};

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum EvictionReason {
    Expired,
    Lru,
    Memory,
}

pub struct CacheConfig {
    pub max_entries: usize,
    pub default_ttl_ms: u64,
    pub max_memory_bytes: usize,
    pub eviction_check_interval_ms: u64,
    pub on_evict: Option<Arc<dyn Fn(&str, EvictionReason) + Send + Sync + 'static>>,
}

impl Default for CacheConfig {
    fn default() -> Self {
        Self {
            max_entries: 1000,
            default_ttl_ms: 60000,
            max_memory_bytes: 100 * 1024 * 1024,
            eviction_check_interval_ms: 5000,
            on_evict: None,
        }
    }
}

#[derive(Debug, Clone, Default)]
pub struct CacheStats {
    pub hits: usize,
    pub misses: usize,
    pub evictions: usize,
    pub expirations: usize,
    pub size: usize,
    pub memory: usize,
}

pub struct PutOptions {
    pub ttl_ms: Option<u64>,
    pub size: Option<usize>,
}

impl Default for PutOptions {
    fn default() -> Self {
        Self { ttl_ms: None, size: None }
    }
}

struct CacheEntry<V> {
    value: Arc<V>,
    expires_at: u64,
    size: usize,
    last_accessed: u64,
    access_count: usize,
    access_id: u64,
}

struct LruCacheState<V> {
    entries: HashMap<Arc<String>, CacheEntry<V>>,
    // Stores (key, access_id) to avoid O(N) removals. Stale entries are ignored.
    access_order: VecDeque<(Arc<String>, u64)>,
    config: CacheConfig,
    current_memory: usize,
    stats: CacheStats,
    weak_refs: HashMap<Arc<String>, Weak<V>>,
    next_access_id: u64,
}

impl<V> LruCacheState<V> {
    fn now_ms() -> u64 {
        SystemTime::now().duration_since(UNIX_EPOCH).unwrap().as_millis() as u64
    }

    fn delete(&mut self, key: &String, reason: EvictionReason) -> bool {
        if let Some(entry) = self.entries.remove(key) {
            self.current_memory -= entry.size;
            self.weak_refs.remove(key);

            if reason == EvictionReason::Expired {
                self.stats.expirations += 1;
            } else {
                self.stats.evictions += 1;
            }

            if let Some(cb) = &self.config.on_evict {
                cb(key, reason);
            }
            true
        } else {
            false
        }
    }

    fn evict_lru(&mut self, reason: EvictionReason) {
        while let Some((key, access_id)) = self.access_order.pop_front() {
            if let Some(entry) = self.entries.get(&key) {
                if entry.access_id == access_id {
                    let key_str = key.to_string();
                    self.delete(&key_str, reason);
                    break;
                }
            }
        }
    }

    fn evict_expired(&mut self) {
        let now = Self::now_ms();
        let mut to_remove = Vec::new();

        for (k, entry) in &self.entries {
            if now > entry.expires_at {
                to_remove.push((k.to_string(), EvictionReason::Expired));
            }
        }

        for (k, ref_weak) in &self.weak_refs {
            if ref_weak.upgrade().is_none() && self.entries.contains_key(k) {
                to_remove.push((k.to_string(), EvictionReason::Memory));
            }
        }

        for (k, reason) in to_remove {
            self.delete(&k, reason);
        }
    }
}

pub struct LruCache<V> {
    state: Arc<Mutex<LruCacheState<V>>>,
    eviction_task: Mutex<Option<JoinHandle<()>>>,
}

impl<V: Send + Sync + 'static> LruCache<V> {
    pub fn new(config: CacheConfig) -> Self {
        Self {
            state: Arc::new(Mutex::new(LruCacheState {
                entries: HashMap::new(),
                access_order: VecDeque::new(),
                config,
                current_memory: 0,
                stats: CacheStats::default(),
                weak_refs: HashMap::new(),
                next_access_id: 1,
            })),
            eviction_task: Mutex::new(None),
        }
    }

    pub fn get(&self, key: &str) -> Option<Arc<V>> {
        let mut state = self.state.lock().unwrap();
        let now = LruCacheState::<V>::now_ms();

        if let Some(entry) = state.entries.get_mut(key) {
            if now > entry.expires_at {
                let key_owned = key.to_string();
                state.delete(&key_owned, EvictionReason::Expired);
                state.stats.misses += 1;
                return None;
            }

            entry.last_accessed = now;
            entry.access_count += 1;
            state.next_access_id += 1;
            entry.access_id = state.next_access_id;

            // Re-queue to back (avoids clone of underlying string via Arc)
            let arc_key = state.entries.get_key_value(key).unwrap().0.clone();
            state.access_order.push_back((arc_key, entry.access_id));
            state.stats.hits += 1;

            Some(Arc::clone(&entry.value))
        } else {
            state.stats.misses += 1;
            None
        }
    }

    pub fn put(&self, key: String, value: V, options: PutOptions) {
        let mut state = self.state.lock().unwrap();
        let size = options.size.unwrap_or(8); // basic estimate
        let ttl = options.ttl_ms.unwrap_or(state.config.default_ttl_ms);
        let max_memory = state.config.max_memory_bytes;
        let max_entries = state.config.max_entries;

        if let Some(old) = state.entries.get(&key) {
            state.current_memory -= old.size;
        }

        while state.current_memory + size > max_memory && !state.access_order.is_empty() {
            state.evict_lru(EvictionReason::Memory);
        }

        while state.entries.len() >= max_entries && !state.access_order.is_empty() {
            state.evict_lru(EvictionReason::Lru);
        }

        let arc_key = Arc::new(key.clone());
        let arc_val = Arc::new(value);
        state.next_access_id += 1;
        let access_id = state.next_access_id;

        let entry = CacheEntry {
            value: Arc::clone(&arc_val),
            expires_at: LruCacheState::<V>::now_ms() + ttl,
            size,
            last_accessed: LruCacheState::<V>::now_ms(),
            access_count: 0,
            access_id,
        };

        state.entries.insert(arc_key.clone(), entry);
        state.current_memory += size;
        state.access_order.push_back((arc_key.clone(), access_id));
        state.weak_refs.insert(arc_key, Arc::downgrade(&arc_val));
    }

    pub fn delete(&self, key: &str, reason: EvictionReason) -> bool {
        self.state.lock().unwrap().delete(&key.to_string(), reason)
    }

    pub fn has(&self, key: &str) -> bool {
        let mut state = self.state.lock().unwrap();
        if let Some(entry) = state.entries.get(key) {
            if LruCacheState::<V>::now_ms() > entry.expires_at {
                let key_owned = key.to_string();
                state.delete(&key_owned, EvictionReason::Expired);
                return false;
            }
            return true;
        }
        false
    }

    pub fn size(&self) -> usize {
        self.state.lock().unwrap().entries.len()
    }

    pub fn memory_usage(&self) -> usize {
        self.state.lock().unwrap().current_memory
    }

    pub fn get_stats(&self) -> CacheStats {
        let state = self.state.lock().unwrap();
        let mut stats = state.stats.clone();
        stats.size = state.entries.len();
        stats.memory = state.current_memory;
        stats
    }

    pub fn clear(&self) {
        let mut state = self.state.lock().unwrap();
        let keys: Vec<String> = state.entries.keys().map(|k| k.to_string()).collect();
        for k in keys {
            state.delete(&k, EvictionReason::Lru);
        }
    }

    pub fn start_eviction_loop(&self) {
        let mut task_guard = self.eviction_task.lock().unwrap();
        if task_guard.is_some() {
            return;
        }

        let state_clone = Arc::clone(&self.state);
        let interval_ms = state_clone.lock().unwrap().config.eviction_check_interval_ms;

        let handle = tokio::spawn(async move {
            let mut timer = interval(Duration::from_millis(interval_ms));
            loop {
                timer.tick().await;
                state_clone.lock().unwrap().evict_expired();
            }
        });

        *task_guard = Some(handle);
    }

    pub fn stop_eviction_loop(&self) {
        let mut task_guard = self.eviction_task.lock().unwrap();
        if let Some(handle) = task_guard.take() {
            handle.abort();
        }
    }
}
