### `src/main.rs`

```rust
mod lib;

#[tokio::main]
async fn main() {
    println!("Run `cargo test` to execute the ported tests.");
}

#[cfg(test)]
mod tests {
    use super::lib::{CacheConfig, LruCache, PutOptions};
    use std::time::Duration;
    use tokio::time::sleep;

    #[tokio::test]
    async fn test_cache() {
        let config = CacheConfig {
            max_entries: 3,
            default_ttl_ms: 100,
            ..Default::default()
        };
        let cache = LruCache::<String>::new(config);

        // Basic get/put
        cache.put("a".into(), "hello".into(), PutOptions::default());
        assert_eq!(*cache.get("a").unwrap(), "hello", "basic get");
        assert_eq!(cache.size(), 1, "size after put");

        // LRU eviction
        cache.put("b".into(), "world".into(), PutOptions::default());
        cache.put("c".into(), "foo".into(), PutOptions::default());
        cache.put("d".into(), "bar".into(), PutOptions::default()); // should evict 'a'
        assert!(!cache.has("a"), "lru eviction");
        assert!(cache.has("d"), "newest kept");

        // TTL expiration
        cache.clear();
        cache.put("x".into(), "temp".into(), PutOptions { ttl_ms: Some(50), ..Default::default() });
        sleep(Duration::from_millis(80)).await;
        assert!(cache.get("x").is_none(), "ttl expired");

        // Access order
        cache.clear();
        cache.put("1".into(), "one".into(), PutOptions::default());
        cache.put("2".into(), "two".into(), PutOptions::default());
        cache.put("3".into(), "three".into(), PutOptions::default());
        cache.get("1"); // access '1', making '2' the LRU
        cache.put("4".into(), "four".into(), PutOptions::default()); // should evict '2'
        assert!(!cache.has("2"), "access order eviction");
        assert!(cache.has("1"), "accessed item kept");

        // Stats
        let stats = cache.get_stats();
        assert!(stats.hits > 0, "has hits");
        assert!(stats.misses > 0, "has misses");

        // Eviction loop
        let config2 = CacheConfig {
            max_entries: 10,
            default_ttl_ms: 50,
            eviction_check_interval_ms: 30,
            ..Default::default()
        };
        let cache2 = LruCache::<String>::new(config2);
        cache2.put("e1".into(), "val1".into(), PutOptions::default());
        cache2.start_eviction_loop();
        sleep(Duration::from_millis(150)).await;
        assert!(!cache2.has("e1"), "eviction loop cleared expired");
        cache2.stop_eviction_loop();

        println!("All tests passed");
    }
}
